jQuery(window).on("load", function() {
    // Fade out the preloader
    $('#preloader').fadeOut(500);
    $('#main-wrapper').addClass('show');

    // Retrieve the stored sidebar state or default to 'collapsed'
    const sidebarState = localStorage.getItem('sidebarState') || 'collapsed';

    if (sidebarState === 'collapsed') {
        $('#main-wrapper').addClass('menu-toggle'); // Add collapsed class
        $(".hamburger").addClass('is-active'); // Reflect collapsed icon state
    } else {
        $('#main-wrapper').removeClass('menu-toggle'); // Ensure expanded class is removed
        $(".hamburger").removeClass('is-active'); // Reflect expanded icon state
    }
});

(function($) {
    "use strict";

    $("#menu").metisMenu();

    $('.nk-nav-scroll').slimscroll({
        position: "right",
        size: "5px",
        height: "100%",
        color: "transparent"
    });

    // Sidebar toggle functionality
    $(".nav-control").on('click', function() {
        // Toggle the sidebar collapse state
        $('#main-wrapper').toggleClass("menu-toggle");
        $(".hamburger").toggleClass("is-active");

        // Save the new state to localStorage
        const sidebarState = $('#main-wrapper').hasClass('menu-toggle') ? 'collapsed' : 'expanded';
        localStorage.setItem('sidebarState', sidebarState);
    });

    // Highlight active menu items
    $(function() {
        for (var nk = window.location, 
            o = $("ul#menu a").filter(function() {
                    return this.href == nk;
                })
                .addClass("active")
                .parent()
                .addClass("active");;) {
            if (!o.is("li")) break;
            o = o.parent()
                .addClass("in")
                .parent()
                .addClass("active");
        }
    });

    // Adjust content-body height
    $(function() {
        var win_h = window.outerHeight;
        if (win_h > 0 ? win_h : screen.height) {
            $(".content-body").css("min-height", (win_h + 60) + "px");
        }
    });

    $('.selectpicker').selectpicker();

    $('[data-toggle="popover"]').popover();
    $('[data-toggle="tooltip"]').tooltip();

    const headerHight = $('.header').innerHeight();

    $(window).scroll(function() {
        if ($('body').attr('data-layout') === "horizontal" 
            && $('body').attr('data-header-position') === "static" 
            && $('body').attr('data-sidebar-position') === "fixed") {
            $(this.window).scrollTop() >= headerHight 
                ? $('.metismenu').addClass('fixed') 
                : $('.metismenu').removeClass('fixed');
        }
    });

    // Sidebar right toggle
    $('.sidebar-right-trigger').on('click', function() {
        $('.sidebar-right').toggleClass('show');
    });

})(jQuery);
